                Job(
                    clip: clip.id, media: media, name: snapshot.name(of: clip), source: url,
                    sourceIn: min(max(0, sourceIn), maxSourceTicks),
                    sourceLength: contentLength(of: clip),
                    start: clip.start, duration: clip.duration, speed: clip.speed))
